    ctx.checkSystemPrivilege(SystemPrivilege.ControlAccess);  // ADD THIS LINE
    ...
}

public void listPrivileges(Context ctx, Empty request, Observer<ListPrivilegesResponse> observer) {
    ctx.checkSystemPrivilege(SystemPrivilege.ControlAccess);  // ADD THIS LINE
    ...
